import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第96章 橙子","description":"","frontmatter":{},"headers":[],"relativePath":"第96章_橙子.md","filePath":"第96章_橙子.md"}'),u={name:"第96章_橙子.md"};function _(q,p,r,n,s,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第96章-橙子" tabindex="-1">第96章 橙子 <a class="header-anchor" href="#第96章-橙子" aria-label="Permalink to &quot;第96章 橙子&quot;">​</a></h1><p>第二年九月，她回来了。</p><p>落地那天她给我发了一张橙子的照片。</p><p>不是新号，也不是旧号。</p><p>是旧号。</p><p>那张照片上是一箱橙子，堆在超市的免费架旁边，纸箱开了一个口，露出三层。</p><p>配的文字是四个字：我落地了。</p><p>我知道这四个字的分量。</p><p>因为她上一次在旧号上发这四个字的时候，她后面跟着的是一句&quot;一切都好，放心&quot;。</p><p>这一次没有&quot;放心&quot;。</p><p>我回了一句：你在哪儿。</p><p>她说，我在机场外面等车。</p><p>我说，你什么时候安顿好。</p><p>她说，我今天到我家。</p><p>我说，你直接回家？</p><p>她说，我不回家我住哪儿。</p><p>我说，你不先讲一声。</p><p>她隔了很久。</p><p>她说，我讲了你要来。</p><p>我说，我要来。</p><p>她说，我知道。</p><p>她说，所以我不讲。</p><p>那天晚上十一点，她在她家那个小区楼下的公共信号上连了一次很差的网。</p><p>她给我打了一段。</p><p>她说，我今天在飞机上睡了三小时。</p><p>她说，我今天在我家那个阳台上站了一会儿。</p><p>她说，阳台栏杆换了，换成铁的，我不喜欢。</p><p>她说，我妈在厨房里煮东西。</p><p>她说，我进门的时候她没回头，她说&quot;鞋在底下&quot;。</p><p>她说，我这一辈子听到的最难受的一句欢迎，就是&quot;鞋在底下&quot;。</p><p>我说，那你呢。</p><p>她说，我&quot;哦&quot;了一声。</p><p>她说，我进了我自己的那间屋。</p><p>她说，我那个屋还在。</p><p>她说，他们给我留着，里面放的是我妹的东西。</p><p>她说，我妹的东西今天全部搬走了。</p><p>她说，我坐在那个床上，那个床上有一块圆形的印子，是我妹那把转椅压出来的。</p><p>她说，我在那个印子上坐了一小时。</p><p>我说，你现在在干什么。</p><p>她说，我现在在楼下。</p><p>她说，我在楼下这个公共椅子上坐着，我这里连的是隔壁那个店。</p><p>她说，我今天不能在我那个屋里给你讲。</p><p>她说，我妈十二点会来关门。</p><p>我说，你明天要干什么。</p><p>她说，我明天去办一个东西。</p><p>我说，办什么。</p><p>她说，我把学籍上那个东西彻底转走。</p><p>她说，我要回这边重新进一个。</p><p>我说，你进哪个。</p><p>她说，我进一个美院的进修班，我九月报名，我要读两年。</p><p>她说，两年以后我不一定读得出。</p><p>我说，那两年钱。</p><p>她说，三万那笔够一年。</p><p>我说，剩下的一年。</p><p>她说，我接活。</p><p>我说，你又要一天打两份。</p><p>她说，我这辈子就是这样。</p><p>她说，你别用那种语气。</p><p>她说，我这次是自己选的。</p><p>她说，我自己选的这一条，跟我妈替我挑的那一条，钱是一样的。</p><p>她说，累也是一样的。</p><p>她说，只有名字不一样。</p><p>她说，名字一样以后，我不恨了。</p><p>我说，那你恨谁。</p><p>她说，我谁也不恨。</p><p>她说，我今天落地以后想明白一件事。</p><p>她说，我以前一直恨我一个人。</p><p>我说，谁。</p><p>她说，我自己。</p><p>她说，因为我这一年我拿了两万八的展费、三万的卡、一个铁盒、一张&quot;未参加&quot;的回执。</p><p>她说，我全部拿着，然后我跟我自己讲&quot;我不配&quot;。</p><p>她说，我今天在阳台上想，我要是把这笔账自己认下来，我就不用再恨我自己。</p><p>她说，我认了。</p><p>她说，我今天认完，我在阳台上站了一会儿，我妈在底下喊吃饭。</p><p>她说，我下去我吃了两碗。</p><p>我说，那挺好。</p><p>她说，你又&quot;那挺好&quot;。</p><p>我说，我今天想不出别的。</p><p>她说，你想不出别的，你就讲你今天。</p><p>我说，我今天在实验室弄到十一点。</p><p>她说，你为什么弄到十一点。</p><p>我说，我在等我这边十一点，因为你那边是下午三点，你在路上。</p><p>她说，你现在不用算了。</p><p>她说，我现在跟你只差五个小时。</p><p>她说，你十一点，我这里下午六点。</p><p>她说，你以后十一点，我这边是晚饭。</p><p>她说，我们两个这一辈子第一次，你的深夜是我的饭点。</p><p>她这句话讲完，我坐在那儿没动。</p><p>我在算她说得对不对。</p><p>她那边比我慢五个小时。</p><p>我晚上十一点，她那边下午六点。</p><p>我算了三年&quot;我这边的十二点是她那边的七点&quot;。</p><p>我现在算的是：我十一点，她在吃饭。</p><p>我算出来了另一个东西。</p><p>我说，那我要是早上七点起，你那边是夜里两点。</p><p>她说，对。</p><p>我说，那我早上你不在。</p><p>她说，你以前也不在。</p><p>她说，你只是以前不在得远。</p><p>我说，那你今天能接我电话吗。</p><p>她说，六点我能接。</p><p>我说，六点你在干嘛。</p><p>她说，六点我在跟我妈做饭。</p><p>我说，那你接了你要出去。</p><p>她说，我出去她听见。</p><p>我说，那你今天先不接。</p><p>她说，你今天讲这句很快。</p><p>我说，我算了一下，我今天就只能讲这句。</p><p>她说，你看，你今年会自己算了。</p><p>她说，我以前算，你算，我们两个人一天到晚在算同一张表。</p><p>她说，我今天在机场外面看那张表，我忽然发现上面多了一个人。</p><p>我说，谁。</p><p>她说，我妈也开始在上面算了。</p><p>她说，她今天问我明天想吃什么。</p><p>她说，她问我这句话的时候，她在算我明天能不能起得晚。</p><p>我说，你现在回来，我们两个中间隔的是什么。</p><p>她隔了很久。</p><p>她说，隔的是五个小时，和一屋子的、能拿起我手机的人。</p><p>她说，前者变近了。</p><p>她说，后者从来没变。</p><p>那天夜里她十一点半下线。</p><p>下线前她发了一句。</p><p>她说，你明年不要报宁城了。</p><p>我说，我不报了。</p><p>她说，你去哪儿。</p><p>我说，我留在这儿。</p><p>她说，好。</p><p>她说，那我们隔五个小时。</p><p>我说，五个小时能过完一辈子吗。</p><p>她说，我不知道。</p><p>她说，你这辈子第一次问这种问题。</p><p>我说，因为我今年手里什么都没有，我只能问。</p><p>她说，你手里有一本本子。</p><p>她说，和一个箱子。</p><p>她说，你别把这两个东西当零。</p><p>她挂了。</p><p>那天夜里我把那个箱子从床底下拖出来。</p><p>我把胶带拆开。</p><p>我一件一件把里面的东西摆在桌上。</p><p>她的三十多件周边。</p><p>两个娃娃。</p><p>一袋小卡。</p><p>阿婆的铁盒。</p><p>我的本子。</p><p>我算&quot;以后&quot;的那张纸。</p><p>那个窗。</p><p>一张回执，上面写着&quot;该生于本年度未被录取&quot;。</p><p>我那天夜里一样一样看了一遍。</p><p>看完我全部放回去。</p><p>我封了两道胶带。</p><p>我推回床底下。</p><p>我这一辈子第一次觉得：这个屋子里最像我的地方的，是一个我不属于自己的箱子。</p>',152)])])}const l=t(u,[["render",_]]);export{d as __pageData,l as default};
